"""Display the results generated by detection.evaluate."""

import pandas as pd
import plotly.express as px
import streamlit as st


FLEET_LABELS = {
    "fleetA_test": "Fleet A · held-out routers",
    "fleetB": "Fleet B · separate fleet",
}
CLASS_LABELS = {
    "normal": "Normal",
    "benign_unusual": "Harmless but unusual",
    "brute_force": "Password guessing",
    "botnet": "Botnet",
}
METRICS = (
    ("attack_recall", "Attack episodes detected", ".1%"),
    ("correct_type_rate", "Correct type among detected attacks", ".1%"),
    ("botnet_early_rate", "Botnets detected before the loud phase", ".1%"),
    ("median_delay_min", "Median delay (simulated minutes)", ".3g"),
    ("p90_delay_min", "90th percentile delay (simulated minutes)", ".3g"),
    ("false_per_router_day", "False incidents per normal router-day", ".3f"),
)
LOOKALIKE_OUTCOMES = {
    "no_incident": "No incident",
    "advisory": "Advisory",
    "unknown_anomaly": "Unknown anomaly",
    "mistaken_for_attack": "Mistaken for an attack",
}


def _display(value, number_format: str) -> str:
    return format(value, number_format) if value is not None else "—"


def _attack_recall(scenarios: dict, prefix: str) -> str:
    variants = [row for scenario, row in scenarios.items() if scenario.startswith(prefix)]
    total = sum(row["episodes"] for row in variants)
    caught = sum(row["caught"] for row in variants)
    return f"{caught}/{total} ({caught / total:.1%})" if total else "—"


def render_evaluation(report: dict) -> None:
    """Show incident-level results, classifier performance, and look-alikes."""
    sets = report.get("sets", {})
    fleet_options = [key for key in FLEET_LABELS if key in sets]
    if not fleet_options:
        st.warning("This evaluation file has no results for the demo fleets.")
        return

    fleet = st.radio(
        "Evaluation fleet",
        fleet_options,
        format_func=FLEET_LABELS.__getitem__,
        horizontal=True,
    )
    results = sets[fleet]
    models = results["models"]
    rules = results["rules"]

    st.caption(
        f"Model {report['model_version']} · {models['routers']} routers "
        f"· {models['attack_episodes']} attack episodes"
    )
    st.caption(report["note"])
    cards = (
        ("Botnets detected", _attack_recall(models["by_scenario"], "botnet_")),
        ("Password guessing detected", _attack_recall(models["by_scenario"], "brute_force_")),
        ("Early botnet detection", _display(models["botnet_early_rate"], ".1%")),
        ("Median delay (min)", _display(models["median_delay_min"], ".3g")),
        ("False incidents / router-day", _display(models["false_per_router_day"], ".3f")),
    )
    for column, (label, value) in zip(st.columns(len(cards)), cards, strict=True):
        column.metric(label, value)

    st.markdown("#### Models vs. rules")
    st.dataframe(
        pd.DataFrame(
            [
                {
                    "Metric": label,
                    "Models": _display(models[key], number_format),
                    "Simple rules": _display(rules[key], number_format),
                }
                for key, label, number_format in METRICS
            ]
        ),
        hide_index=True,
    )
    st.caption(
        "Early detection measures botnets with a scheduled loud phase. "
        "Delay measures detected attacks in simulated minutes."
    )

    st.markdown("#### Harmless look-alikes")
    st.dataframe(
        pd.DataFrame(
            [
                {
                    "Method": label,
                    **{
                        heading: metrics["lookalike_outcomes"].get(outcome, 0)
                        for outcome, heading in LOOKALIKE_OUTCOMES.items()
                    },
                }
                for label, metrics in (("Models", models), ("Simple rules", rules))
            ]
        ),
        hide_index=True,
    )

    st.markdown("#### Random Forest confusion matrix")
    minute = results["minute"]
    classes = [CLASS_LABELS.get(name, name) for name in minute["rf_classes"]]
    matrix = px.imshow(
        minute["rf_confusion"],
        x=classes,
        y=classes,
        labels={"x": "Predicted class", "y": "Actual class", "color": "Router-minutes"},
        text_auto=True,
        color_continuous_scale="Blues",
        aspect="auto",
    )
    matrix.update_layout(height=400, margin={"l": 0, "r": 0, "t": 10, "b": 0})
    st.plotly_chart(matrix)
    st.caption("Each cell counts simulated router-minutes. The tables above count episodes.")
